cli.mjs.text:
#!/usr/bin/env node
// CLI: price video hosting (Cloudflare Stream, Mux, Bunny Stream, api.video, DIY AWS) at a stored
// library, monthly minutes watched and monthly minutes uploaded, project 12 months of growth and
// find the viewing level where the cheapest platform changes. No network.
// Exit 0 ok, 1 over --budget, 2 bad input.
import { readFileSync } from "node:fs";
import { DEFAULT_PROVIDERS, PRICES_AS_OF, compare, project, cheapestSegments, summarize, fmt } from "./engine.mjs";

const USAGE = `usage: node cli.mjs compare --stored-min <n> --watched-min <n> [--uploaded-min <n>] [--growth <pct/month>] [--months <n>] [--provider <key>] [--budget <usd/month>] [--prices file.json] [--json]
       node cli.mjs crossover --stored-min <n> [--uploaded-min <n>] [--prices file.json] [--max <watched min>] [--json]
       node cli.mjs providers

--prices is a JSON object of provider overrides, merged over the defaults, e.g.
  {"mux":{"deliveryPerMin":0.0006,"includedDeliveryMin":100000}}`;

function fail(msg) { console.error(msg); process.exit(2); }

function loadProviders(file) {
  const merged = JSON.parse(JSON.stringify(DEFAULT_PROVIDERS));
  if (!file) return merged;
  let over;
  try { over = JSON.parse(readFileSync(file, "utf8")); } catch (e) { fail(`could not read --prices ${file}: ${e.message}`); }
  for (const [k, v] of Object.entries(over)) merged[k] = { ...(merged[k] || { label: k, url: "", baseUsd: 0, storagePerMin: 0, includedStorageMin: 0, deliveryPerMin: 0, includedDeliveryMin: 0, encodePerMin: 0 }), ...v };
  return merged;
}

const argv = process.argv.slice(2);
const cmd = argv.shift();
const opt = {};
const flags = new Set(["json"]);
for (let i = 0; i < argv.length; i++) {
  const a = argv[i];
  if (!a.startsWith("--")) fail(`unexpected argument "${a}"\n${USAGE}`);
  const k = a.slice(2);
  if (flags.has(k)) opt[k] = true;
  else { if (argv[i + 1] === undefined) fail(`--${k} needs a value`); opt[k] = argv[++i]; }
}
const num = (k, d) => {
  if (opt[k] === undefined) return d;
  const n = Number(opt[k]);
  if (!Number.isFinite(n) || n < 0) fail(`--${k} needs a non-negative number, got "${opt[k]}"`);
  return n;
};
const n0 = (n) => n.toLocaleString("en-US");

if (cmd === "providers") {
  for (const [k, p] of Object.entries(DEFAULT_PROVIDERS)) console.log(`${k.padEnd(9)} ${p.label.padEnd(66)} $${p.storagePerMin}/min stored  $${p.deliveryPerMin}/min watched  ${p.url}`);
  console.log(`\n${PRICES_AS_OF}`);
} else if (cmd === "compare") {
  if (opt["stored-min"] === undefined || opt["watched-min"] === undefined) fail(`--stored-min and --watched-min are required\n${USAGE}`);
  const providers = loadProviders(opt.prices);
  const stored = num("stored-min"), watched = num("watched-min"), up = num("uploaded-min", 0);
  const rows = compare(stored, watched, up, providers);
  const proj = project(stored, watched, up, num("growth", 0), num("months", 12), providers);
  const s = summarize(rows, { budget: opt.budget === undefined ? null : num("budget"), provider: opt.provider || null });
  if (s.status === "error" && s.errors === 1 && !s.overBudget) fail(s.text);
  if (opt.json) console.log(JSON.stringify({ storedMin: stored, watchedMin: watched, uploadedMin: up, rows, projection: proj, summary: s }, null, 2));
  else {
    console.log(`${n0(stored)} min stored, ${n0(watched)} min watched and ${n0(up)} min uploaded a month\n`);
    for (const r of rows) console.log(`${r.label.padEnd(68)} ${fmt(r.monthly).padStart(12)}/mo  ${fmt(r.annual).padStart(14)}/yr${r.extraVsCheapest ? `  (+${fmt(r.extraVsCheapest)})` : ""}`);
    console.log(`\n${num("months", 12)}-month spend at ${num("growth", 0)}%/mo growth (${n0(stored)} -> ${n0(proj.endStored)} min stored, ${n0(proj.endDelivered)} min watched a month at the end):`);
    for (const t of proj.totals) console.log(`${t.label.padEnd(68)} ${fmt(t.total).padStart(14)}`);
    console.log(`\n${s.text}\n${PRICES_AS_OF}. Not a quote.`);
  }
  process.exit(s.overBudget ? 1 : 0);
} else if (cmd === "crossover") {
  if (opt["stored-min"] === undefined) fail(`--stored-min is required\n${USAGE}`);
  const segs = cheapestSegments(num("stored-min"), num("uploaded-min", 0), loadProviders(opt.prices), num("max", 50000000));
  if (opt.json) console.log(JSON.stringify(segs, null, 2));
  else for (const s of segs) console.log(`${String(s.from).padStart(9)} - ${String(s.to).padStart(9)} min watched   cheapest: ${s.label}`);
} else fail(USAGE);

